(function(){"use strict";var LIMITS={"fb-title":80,"fb-message":10000,"fb-reply":10000};function counterFor(id){return document.querySelector('[data-counter-for="'+id+'"]');}
function updateCounter(field){var out=counterFor(field.id);if(!out)return;var limit=LIMITS[field.id]||0;var used=Array.from(field.value).length;out.textContent=used+" / "+limit;out.classList.toggle("fb-counter-over",limit>0&&used>limit);}
function fieldError(field,text){var hintId=field.getAttribute("aria-describedby");var hint=hintId?document.getElementById(hintId):null;var box=field.parentNode.querySelector(".fb-field-error");if(!box){box=document.createElement("p");box.className="fb-field-error";box.setAttribute("role","alert");box.id=field.id+"-error";field.parentNode.appendChild(box);}
box.textContent=text;field.setAttribute("aria-invalid","true");field.setAttribute("aria-describedby",((hint&&hint.id)?hint.id+" ":"")+box.id);field.focus();}
function clearFieldError(field){var box=field.parentNode.querySelector(".fb-field-error");if(box)box.remove();field.removeAttribute("aria-invalid");var described=field.getAttribute("aria-describedby")||"";field.setAttribute("aria-describedby",described.replace(field.id+"-error","").trim());}
function validate(form){var fields=form.querySelectorAll("input[type=text][name=title], textarea[name=message]");for(var i=0;i<fields.length;i++){var field=fields[i];clearFieldError(field);var value=field.value.trim();var limit=LIMITS[field.id]||0;if(!value){fieldError(field,field.name==="title"?"Напиши заголовок - по нему обращение находят в списке.":"Сообщение пустое.");return false;}
if(limit&&Array.from(value).length>limit){fieldError(field,"Слишком длинно: "+Array.from(value).length+" из "+limit+" символов.");return false;}}
return true;}
function initForm(form){form.addEventListener("submit",function(event){if(!validate(form)){event.preventDefault();return;}
var button=form.querySelector(".fb-submit");if(button){button.classList.add("fb-submit-busy");button.textContent="Отправляю...";setTimeout(function(){button.disabled=true;},0);}});form.querySelectorAll("input[type=text][name=title], textarea[name=message]").forEach(function(field){updateCounter(field);field.addEventListener("input",function(){updateCounter(field);clearFieldError(field);});});}
function initAdminConfirm(){document.querySelectorAll("[data-confirm]").forEach(function(button){button.addEventListener("click",function(event){if(!window.confirm(button.getAttribute("data-confirm"))){event.preventDefault();}});});}
document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".fb-form").forEach(initForm);initAdminConfirm();var flash=document.getElementById("fb-flash");if(flash)flash.focus();});})();
